@router.get("/streams/telemetry/subscribe")
async def subscribe_facility_telemetry(
    facility_code: str = Query(...),
    redis: Redis = Depends(get_redis_client),
    current_user: User = Depends(get_current_user)
):
    if facility_code not in current_user.permitted_facilities and not current_user.is_security_admin:
        raise HTTPException(status_code=403, detail="Forbidden: access to facility telemetry stream denied")

    async def event_publisher():
        pubsub = redis.pubsub()
        await pubsub.psubscribe(f"telemetry:{facility_code}:*")
        try:
            async for message in pubsub.listen():
                if message["type"] == "pmessage":
                    yield f"data: {message['data']}\n\n"
        finally:
            await pubsub.punsubscribe()

    return StreamingResponse(event_publisher(), media_type="text/event-stream")
